/* ===== Visualizador 360 — Homem-Aranha (seção "quem somos") =====
   Crossfade entre 3 fotos reais (frente 0°, esquerda 90°, costas 180°).
   O lado direito (270°) é a foto da esquerda espelhada (aproximação,
   já que não tiramos foto desse ângulo). Sem dependências externas. */
(function () {
  var FRONT = "data:image/png;base64,";
  var LEFT  = "data:image/png;base64,";
  var BACK  = "data:image/png;base64,";

  var root = document.getElementById('f3dViewer');
  if (!root) return;

  var stage = document.getElementById('f3dStage');
  var hint = document.getElementById('f3dHint');
  var slider = document.getElementById('f3dSlider');

  // 4 keyframes around 360°: front, left, back, right(=left mirrored)
  var frames = [];
  [FRONT, LEFT, BACK, LEFT].forEach(function (src, i) {
    var img = document.createElement('img');
    img.src = src;
    img.className = 'f3d-frame';
    img.style.opacity = i === 0 ? '1' : '0';
    img.draggable = false;
    if (i === 3) img.style.transform = 'scaleX(-1)';
    stage.appendChild(img);
    frames.push(img);
  });

  var angle = 0; // 0..360
  var velocity = 0;
  var isDragging = false, lastX = 0;

  function hideHint() { hint && hint.classList.add('f3d-hidden'); }

  function render() {
    var a = ((angle % 360) + 360) % 360;
    var seg = a / 90;
    var idx = Math.floor(seg);
    var t = seg - idx;
    for (var i = 0; i < 4; i++) frames[i].style.opacity = '0';
    frames[idx].style.opacity = String(1 - t);
    frames[(idx + 1) % 4].style.opacity = String(t);
    if (slider) slider.value = String(a);
  }

  function onDown(e) {
    isDragging = true;
    lastX = e.clientX;
    root.classList.add('f3d-dragging');
    root.setPointerCapture(e.pointerId);
    hideHint();
  }
  function onMove(e) {
    if (!isDragging) return;
    var dx = e.clientX - lastX;
    lastX = e.clientX;
    velocity = dx * 0.35;
    angle += velocity;
    render();
  }
  function onUp() {
    isDragging = false;
    root.classList.remove('f3d-dragging');
  }

  root.addEventListener('pointerdown', onDown);
  root.addEventListener('pointermove', onMove);
  window.addEventListener('pointerup', onUp);

  if (slider) {
    slider.addEventListener('input', function () {
      velocity = 0;
      angle = parseFloat(slider.value);
      render();
      hideHint();
    });
    slider.addEventListener('pointerdown', hideHint);
  }

  function loop() {
    requestAnimationFrame(loop);
    if (!isDragging) {
      velocity *= 0.9;
      if (Math.abs(velocity) > 0.02) {
        angle += velocity;
        render();
      }
    }
  }
  loop();
})();
